// Hide the default main box so it's not in the way
box.visible = false;
// Dutch Cards meaning
let karty = [
    '2','3','4','5','6','7','8','9','10',
    'cierneJ','cierneQ','cierneK','cierneA',
    'cerveneJ','cerveneQ','cerveneK','cerveneA'
];
let kartyHodnota = { 
    "2": { hodnota: 2, funkcia: null },
    "3": { hodnota: 3, funkcia: null },
    "4": { hodnota: 4, funkcia: null },
    "5": { hodnota: 5, funkcia: null },
    "6": { hodnota: 6, funkcia: null },
    "7": { hodnota: 7, funkcia: null },
    "8": { hodnota: 8, funkcia: null },
    "9": { hodnota: 9, funkcia: null },
    "10": { hodnota: 10, funkcia: null },
    "cierneJ": { hodnota: 11, funkcia: null },
    "cierneQ": { hodnota: 12, funkcia: 'Pozriet inu kartu' },
    "cierneK": { hodnota: 20, funkcia: 'Najhorsia karta' },
    "cierneA": { hodnota: 1, funkcia: null },
    "cerveneJ": { hodnota: 11, funkcia: null },
    "cerveneQ": { hodnota: 12, funkcia: 'Pozriet inu kartu' },
    "cerveneK": { hodnota: 0, funkcia: 'Najlepsia karta' },
    "cerveneA": { hodnota: 1, funkcia: null }
};
let cardBoxes = [];
let maxColumns = 6; // How many cards per row
for (let i = 0; i < karty.length; i++) {
    // Create a new Box for this card
    let cardBox = new Box();
    let cardName = karty[i];
    let cardData = kartyHodnota[cardName];
    
    // Make the cards smaller to fit the screen
    cardBox.width = 90;
    cardBox.height = 120;
    
    // ----- MATH FOR GRID LAYOUT -----
    // This calculates row and column based on 'i'
    let row = Math.floor(i / maxColumns);
    let col = i % maxColumns;
    
    // Start at top-left (-300, 200) and step by 100 for X, -140 for Y
    cardBox.x = -300 + (col * 100);
    cardBox.y = 200 - (row * 140);
    
    // ----- COLORS -----
    if (cardName.startsWith("cervene")) {
        cardBox.color = "#ff4757"; // Red
    } else if (cardName.startsWith("cierne")) {
        cardBox.color = "#2f3542"; // Dark Gray/Black
    } else {
        cardBox.color = "#7bed9f"; // Green for numbers
    }
    
    // ----- TEXT -----
    // Combine the name and the value
    cardBox.text = cardName + " (" + cardData.hodnota + ")";
    
    // ----- CLICK EVENT -----
    // When you click a card, it prints info to the console!
    cardBox.onClick = function() {
        console.log("Vybral si kartu:", cardName);
        console.log("Hodnota:", cardData.hodnota);
        if (cardData.funkcia) {
            console.log("!!!", cardData.funkcia, "!!!");
        }
    };
    
    // Save it to our array
    cardBoxes.push(cardBox);
}

